import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Month 2021: Project Aquarium - An easy-to-use storage appliance wrapped around Ceph","description":"","frontmatter":{"title":"Ceph Month 2021: Project Aquarium - An easy-to-use storage appliance wrapped around Ceph","date":"2021-06-16T00:00:00.000Z","updated":"2021-06-17T00:00:00.000Z","tags":["Ceph","Storage Appliance","Project Aquarium","Distributed Storage","Ceph Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Project_Aquarium_-_An_easy-to-use_storage_appliance_wrapped_around_Ceph.md","filePath":"posts/2021/Ceph_Month_2021_-_Project_Aquarium_-_An_easy-to-use_storage_appliance_wrapped_around_Ceph.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Month_2021_-_Project_Aquarium_-_An_easy-to-use_storage_appliance_wrapped_around_Ceph.md"};function n(s,a,l,u,_,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要-project-aquarium-介绍与讨论" tabindex="-1">会议纪要：Project Aquarium 介绍与讨论 <a class="header-anchor" href="#会议纪要-project-aquarium-介绍与讨论" aria-label="Permalink to &quot;会议纪要：Project Aquarium 介绍与讨论&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议由Alex Saddle主持，他是Souza公司的软件工程经理和Project Aquarium的产品负责人。会议重点介绍了Project Aquarium的目标、架构、演示以及未来发展规划。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>项目名称</strong>：Project Aquarium</li><li><strong>项目目标</strong>：简化Ceph的开发、部署和管理，提供一个开源的存储设备解决方案。</li><li><strong>项目团队</strong>：由Souza公司的存储团队开发，Alex Saddle担任产品负责人，另一位高级工程师担任后端负责人。</li><li><strong>项目架构</strong>：分为后端“Gravel”和前端“Glass”，后端使用Python，前端使用Angular。</li><li><strong>技术选择</strong>：作为系统服务运行，依赖fadm等系统工具，使用WebSockets进行通信，并利用fcd维护集群状态。</li><li><strong>用户界面</strong>：提供简化的、引导式的安装和操作界面，抽象复杂概念，不直接暴露底层配置细节。</li><li><strong>演示内容</strong>：展示了安装过程、集群管理以及数据操作和管理。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>短期目标</strong>：改进仪表板，实现对象服务，测试USB启动和Pixie booting。</li><li><strong>中期目标</strong>：关注升级过程，开发块服务和资源约束求解器。</li><li><strong>长期目标</strong>：社区发展和项目扩展，实现“世界统治”（幽默提及）。</li></ul><h4 id="讨论与问答" tabindex="-1">讨论与问答 <a class="header-anchor" href="#讨论与问答" aria-label="Permalink to &quot;讨论与问答&quot;">​</a></h4><ul><li><strong>经验教训</strong>：从Ceph Dashboard的经验中学习，但Aquarium项目有其独特性，不直接竞争，而是提供不同的使用场景。</li><li><strong>技术细节</strong>：使用Python Librados直接与Ceph通信，而不是依赖Dashboard API。</li><li><strong>硬件选择</strong>：目前不特定于特定硬件模型，但未来可能会更具体化。</li><li><strong>使用fcd的原因</strong>：确保Aquarium在Ceph故障时仍能运行，fcd提供必要的集群状态管理。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>Project Aquarium是一个新兴的开源项目，旨在简化Ceph的使用和管理。团队欢迎社区的参与和反馈，并计划通过一系列的改进和扩展来推动项目的发展。</p>',11)])])}const c=e(i,[["render",n]]);export{d as __pageData,c as default};
